INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Auftraggeber eine zentrale Rolle im Projektmanagement?', 2, '[{"text": "Ja", "correct": true, "because": "Definiert Ziele und finanziert"}, {"text": "Nein", "correct": false, "because": "Er ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt der Auftraggeber?', 3, '[{"text": "Projektziele und Ressourcen bereitstellen", "correct": true, "because": "Legt Rahmen fest"}, {"text": "Projekt direkt umsetzen", "correct": false, "because": "Durchführungsaspekt"}, {"text": "Team täglich steuern", "correct": false, "because": "Projektleiteraufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Auftraggeber definiert die Anforderungen. b) Er führt das Projekt aus.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Ausführung durch Team"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt der Auftraggeber?', 4, '[{"text": "Ziele festlegen", "correct": true, "because": "Gibt Richtung"}, {"text": "Tägliche Koordination", "correct": false, "because": "Projektleiteraufgabe"}, {"text": "Ressourcen bereitstellen", "correct": true, "because": "Finanziert Projekt"}, {"text": "Abnahme bestätigen", "correct": true, "because": "Akzeptiert Ergebnisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Auftraggeber starten?', 2, '[{"text": "Nein", "correct": true, "because": "Ziele und Mittel fehlen"}, {"text": "Ja", "correct": false, "because": "Unklarer Auftrag"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Auftraggeber in der Initiierung?', 3, '[{"text": "Projektzweck definieren", "correct": true, "because": "Legt Grundlage"}, {"text": "Technische Umsetzung planen", "correct": false, "because": "Projektleiteraufgabe"}, {"text": "Fortschritt überwachen", "correct": false, "because": "Controlling-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Auftraggeber nur für große Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen ihn"}, {"text": "Ja", "correct": false, "because": "Universelle Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Verantwortung hat der Auftraggeber im Abschluss?', 3, '[{"text": "Abnahme der Ergebnisse", "correct": true, "because": "Bestätigt Erfolg"}, {"text": "Tägliche Steuerung", "correct": false, "because": "Durchführungsaufgabe"}, {"text": "Zeitplan erstellen", "correct": false, "because": "Planungsaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Auftraggeber stellt das Budget bereit. b) Er überwacht tägliche Arbeiten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Projektleiteraufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Auftraggeber?', 3, '[{"text": "Projektziele unklar", "correct": true, "because": "Fehlende Vorgaben"}, {"text": "Projekt wird schneller", "correct": false, "because": "Eher Verzögerung"}, {"text": "Kosten sinken", "correct": false, "because": "Finanzierung fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Auftraggeber ohne Projektleiter agieren?', 2, '[{"text": "Nein", "correct": true, "because": "Projektleiter steuert"}, {"text": "Ja", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Aufgabe des Auftraggebers?', 3, '[{"text": "Ziele im Lastenheft festlegen", "correct": true, "because": "Konkret und real"}, {"text": "Tägliche Aufgaben verteilen", "correct": false, "because": "Projektleiteraufgabe"}, {"text": "Team soll arbeiten", "correct": false, "because": "Zu vage"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Auftraggeber nur für die Finanzierung verantwortlich?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Ziele und Abnahme"}, {"text": "Ja", "correct": false, "because": "Breitere Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat der Auftraggeber?', 4, '[{"text": "Entscheidungsbefugnis", "correct": true, "because": "Legt Rahmen fest"}, {"text": "Tägliche Steuerung", "correct": false, "because": "Projektleiteraufgabe"}, {"text": "Ressourcenverantwortung", "correct": true, "because": "Stellt Mittel"}, {"text": "Abnahmerecht", "correct": true, "because": "Bestätigt Ergebnisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Rolle des Auftraggebers dokumentiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Klarheit wichtig"}, {"text": "Nein", "correct": false, "because": "Dokumentation hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode nutzt der Auftraggeber?', 3, '[{"text": "Lastenheft erstellen", "correct": true, "because": "Definiert Anforderungen"}, {"text": "Keine Planung", "correct": false, "because": "Fehlt Struktur"}, {"text": "Spontane Anweisungen", "correct": false, "because": "Unsystematisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Auftraggeber ohne Stakeholder agieren?', 2, '[{"text": "Nein", "correct": true, "because": "Stakeholder beeinflussen"}, {"text": "Ja", "correct": false, "because": "Abstimmung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Rolle des Auftraggebers?', 3, '[{"text": "Unklare Projektziele", "correct": true, "because": "Verhindern Vorgaben"}, {"text": "Klarer Zeitplan", "correct": false, "because": "Fördert Planung"}, {"text": "Gute Kommunikation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Auftraggeber ist Entscheidungsträger. b) Er ist nur für technische Details zuständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen des Auftraggebers?', 3, '[{"text": "Klare Projektvorgaben", "correct": true, "because": "Fördert Erfolg"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Finanzierung", "correct": false, "because": "Fördert Ressourcen"}]');
